-- Original instructional questions authored for the 2026 professional practice lane.
-- NOT claimed to be questions previously administered in attestatsiya.
-- Source trace flows through M14 / M15 / M16 lessons to official/recommended books.
-- 36 questions: KS 14, PM.GEN 16, PM.MET 6; each of 18 active objectives represented twice.
begin;
do $seed$
declare
  r record;
  v_subject uuid;
  v_construct uuid;
  v_lesson uuid;
  v_qid uuid;
  v_oid uuid;
  i int;
begin
  select id into strict v_subject from public.subjects where code='informatika';
  for r in select * from jsonb_to_recordset($data$[{"n":1,"construct":"KS.01","stem":"Darsni rejalashtirishda birinchi navbatda nimani belgilash maqsadga muvofiq?","options":["Tekshiriladigan o‘quv natijasini","Faqat slaydlar sonini","Sinfdagi partalar joylashuvini","Dars tugash vaqtini"],"answer":0,"explanation":"Reja aniq va baholanadigan o‘quv natijasidan boshlanadi.","cognitive":"bilish","difficulty":2},{"n":2,"construct":"KS.01","stem":"Diagnostikada o‘quvchilar bir mavzuni turli darajada bilishi aniqlandi. Eng asosli rejalash qarori qaysi?","options":["Barcha uchun aynan bir xil topshiriq","Darsni faqat kuchli o‘quvchilarga moslash","Oldingi bilimga qarab differensial topshiriqlar tanlash","Diagnostika natijasini e’tiborsiz qoldirish"],"answer":2,"explanation":"Rejalashda avvalgi bilim va ehtiyojlar hisobga olinadi.","cognitive":"qollash","difficulty":3},{"n":3,"construct":"KS.02","stem":"Darsdagi faol ishtirokni oshirishga xizmat qiluvchi usul qaysi?","options":["Faqat o‘qituvchining uzluksiz monologi","O‘quvchilar yechimni tushuntiradigan hamkorlikdagi vazifa","Barcha amaliy ishlarni bekor qilish","Savollarga javob berishni taqiqlash"],"answer":1,"explanation":"Faol mashg‘ulotlar bilimni qo‘llash va muhokama qilishga imkon yaratadi.","cognitive":"qollash","difficulty":3},{"n":4,"construct":"KS.02","stem":"O‘qituvchi topshiriqni bajarishga qiynalayotgan guruhni aniqladi. Qaysi yechim samaraliroq?","options":["Vazifani yengil bosqichlarga ajratib, mos tayanch ko‘mak berish","Guruhni butunlay mashg‘ulotdan chetlatish","Barcha o‘quvchiga darhol past baho qo‘yish","Mavzuni tushuntirmasdan davom etish"],"answer":0,"explanation":"Moslashtirilgan qo‘llab-quvvatlash ta’lim samaradorligini oshiradi.","cognitive":"qollash","difficulty":3},{"n":5,"construct":"KS.03","stem":"Formativ baholashning asosiy vazifasi nima?","options":["Faqat chorak bahosini hisoblash","O‘quv jarayonida xatolarni aniqlab, qayta aloqa berish","O‘quvchilarni bir-biriga qarshi qo‘yish","Faqat sinov yakunida diplom berish"],"answer":1,"explanation":"Formativ baholash o‘qish jarayonini tuzatishga xizmat qiladi.","cognitive":"bilish","difficulty":2},{"n":6,"construct":"KS.03","stem":"O‘quvchi dasturida xato bor. Qaysi qayta aloqa ko‘proq foydali?","options":["Sening ishing yomon","Birorta izohsiz nol ball","Shart ifodasini qayta tekshir; kichik test qiymati bilan sinab ko‘r","Dastur o‘rniga boshqa o‘quvchi javob bersin"],"answer":2,"explanation":"Aniq va amalga oshiriladigan ko‘rsatma o‘quvchini mustaqil tuzatishga yo‘naltiradi.","cognitive":"qollash","difficulty":3},{"n":7,"construct":"KS.04","stem":"Tarbiyaviy faoliyatda o‘quvchining qadr-qimmatini saqlashga mos yondashuv qaysi?","options":["Xatoni butun sinf oldida masxara qilish","Faqat bir guruhni tinglash","Har bir o‘quvchiga hurmat bilan muomala qilish","O‘quvchilar fikrini taqiqlash"],"answer":2,"explanation":"Hurmat va qadr-qimmat tarbiyaviy faoliyatning muhim tamoyillaridir.","cognitive":"bilish","difficulty":2},{"n":8,"construct":"KS.04","stem":"Sinfda bir o‘quvchi boshqasini kamsitmoqda. O‘qituvchining birinchi pedagogik harakati qaysi?","options":["Holatni e’tiborsiz qoldirish","Kamsitishni to‘xtatish va xavfsiz muloqot qoidalarini tiklash","Jabrlangan o‘quvchini ayblash","Videoni tarmoqqa tarqatish"],"answer":1,"explanation":"Kamsitishning oldini olish va xavfsiz muhitni saqlash ustuvor.","cognitive":"qollash","difficulty":3},{"n":9,"construct":"KS.05","stem":"Kompyuter xonasida xavfsiz ta’lim muhitini ta’minlashga qaysi ish kiradi?","options":["Elektr simlarining butunligini va o‘tish joylarini tekshirish","Nam qo‘l bilan elektr jihoziga tegish","Rozetkalarni ochiq qoldirish","Qurilmalarni nazoratsiz ta’mirlash"],"answer":0,"explanation":"Elektr xavfsizligi va tartib xavfsiz muhitning tarkibiy qismidir.","cognitive":"bilish","difficulty":2},{"n":10,"construct":"KS.05","stem":"O‘quvchi tarmoqda haqoratli xabar oldi. Qaysi harakat xavfsiz rivojlantiruvchi muhitga eng mos?","options":["Xabarni sinf guruhiga tarqatish","Buni odatiy hol deb hisoblash","Maxfiylikni saqlab, zararli aloqani to‘xtatish va tegishli yordam tashkil etish","O‘quvchini jazolash bilan cheklanish"],"answer":2,"explanation":"Kiberzo‘ravonlik holatida himoya, ishonchli yordam va maxfiylik zarur.","cognitive":"mulohaza","difficulty":4},{"n":11,"construct":"KS.06","stem":"Kasbiy rivojlanish rejasini tuzishda qaysi dalil foydali?","options":["Faqat tasodifiy tavsiya","Dars natijalari, o‘zini tahlil qilish va hamkasb fikri","Faqat sinf xonasining maydoni","Telefon rusumi"],"answer":1,"explanation":"Refleksiya va real dalillar o‘sish ehtiyojini aniqlaydi.","cognitive":"bilish","difficulty":2},{"n":12,"construct":"KS.06","stem":"O‘qituvchi yangi baholash metodini qo‘lladi, ammo natija kutilganday bo‘lmadi. Nima qilish to‘g‘ri?","options":["Usulni dalilsiz doim qo‘llash","O‘quvchini ayblab o‘zgarish qilmaslik","Natijani tahlil qilish, metodni moslash va qayta sinab ko‘rish","Baholashdan butunlay voz kechish"],"answer":2,"explanation":"Kasbiy refleksiya natijaga tayangan takomillashtirishni talab qiladi.","cognitive":"qollash","difficulty":3},{"n":13,"construct":"KS.07","stem":"Ota-ona bilan suhbatda o‘quvchi yutuqlarini muhokama qilishda nima muhim?","options":["Boshqa o‘quvchilarning maxfiy baholarini oshkor qilish","Aniq dalil va hurmat asosida rivojlanish yo‘lini kelishish","Faqat muammolarni bo‘rttirib ko‘rsatish","Muloqotni taqiqlash"],"answer":1,"explanation":"Hamkorlikda shaxsiy ma’lumotlarni himoya qilib, dalilga asoslanish kerak.","cognitive":"qollash","difficulty":3},{"n":14,"construct":"KS.07","stem":"Ikki fan o‘qituvchisi raqamli loyiha o‘tkazmoqchi. Hamkorlikning eng samarali ko‘rinishi qaysi?","options":["Vazifalarni kelishmasdan bo‘lish","Har biri bir-birining darsini bekor qilish","Umumiy maqsad, mas’uliyat va baholash mezonini oldindan kelishish","O‘quvchilarga turlicha qarama-qarshi topshiriq berish"],"answer":2,"explanation":"Hamkorlik aniq maqsad va vazifalar muvofiqligini talab qiladi.","cognitive":"mulohaza","difficulty":4},{"n":15,"construct":"PM.GEN.01","stem":"Didaktika nimalarni o‘rganadi?","options":["Faqat maktab binosi loyihasini","O‘qitishning maqsadi, mazmuni, tamoyili va metodlarini","Faqat bolalar ovqatlanishini","Faqat sport musobaqalarini"],"answer":1,"explanation":"Didaktika pedagogikaning ta’lim nazariyasiga oid bo‘limidir.","cognitive":"bilish","difficulty":2},{"n":16,"construct":"PM.GEN.01","stem":"Boshlang‘ich sinfga yangi tushuncha berishda yosh xususiyatlarini hisobga olish qanday ifodalanadi?","options":["Faqat mavhum ta’rif bilan cheklanish","Oldingi tajribani chetga surish","Ko‘rgazmali sodda misoldan tushunchaga o‘tish","Darhol eng murakkab formula berish"],"answer":2,"explanation":"Yosh xususiyatiga mos o‘qitish tushunishni osonlashtiradi.","cognitive":"qollash","difficulty":3},{"n":17,"construct":"PM.GEN.02","stem":"Ilmiylik tamoyiliga mos misolni toping.","options":["Haqiqiyligi noma’lum xabarni fakt sifatida berish","Tekshirilgan dalil va aniq atamalardan foydalanish","Faqat taxminni dalil deb qabul qilish","Xatoni tekshirishni taqiqlash"],"answer":1,"explanation":"Ilmiylik tekshirilgan, asosli bilimga tayanadi.","cognitive":"bilish","difficulty":2},{"n":18,"construct":"PM.GEN.02","stem":"Yangi mavzu oldingisiga tayangan holda bosqichma-bosqich berilmoqda. Bu qaysi tamoyilga misol?","options":["Tizimlilik va izchillik","Tasodifiylik","Jazolash","Nazariyadan voz kechish"],"answer":0,"explanation":"Tizimlilik va izchillik mavzular mantiqiy bog‘liqligini ta’minlaydi.","cognitive":"qollash","difficulty":3},{"n":19,"construct":"PM.GEN.03","stem":"Axloqiy tarbiyaning asosiy yo‘nalishi qaysi?","options":["Hisoblash tezligini oshirish","Hurmat, mas’uliyat va xulq me’yorlarini shakllantirish","Faqat yugurish masofasini oshirish","Kompyuter xotirasini kengaytirish"],"answer":1,"explanation":"Axloqiy tarbiya ijtimoiy me’yor va qadriyatlarga qaratiladi.","cognitive":"bilish","difficulty":2},{"n":20,"construct":"PM.GEN.03","stem":"O‘quvchilar maktab bog‘iga mas’uliyat bilan qarash va hamkorlikda mehnat qilishmoqda. Qaysi tarbiya ustun?","options":["Faqat huquqiy tarbiya","Faqat estetik tarbiya","Mehnat tarbiyasi","Faqat matematik mashq"],"answer":2,"explanation":"Mehnat tarbiyasi mas’uliyatli va hamkorlikdagi mehnat ko‘nikmasini shakllantiradi.","cognitive":"qollash","difficulty":3},{"n":21,"construct":"PM.GEN.04","stem":"Yangi bilimni o‘zlashtirish darsining maqsadiga mos harakat qaysi?","options":["Yangi tushunchani izohlash va misol bilan mustahkamlash","Faqat oldingi bahoni e’lon qilish","Mavzuni bermasdan nazorat olish","Faqat tanaffusni uzaytirish"],"answer":0,"explanation":"Dars turi asosiy didaktik maqsadga qarab tanlanadi.","cognitive":"bilish","difficulty":2},{"n":22,"construct":"PM.GEN.04","stem":"Sinfda bir nechta o‘quvchi mashg‘ulotdan chalg‘iyapti. Qaysi boshqaruv usuli eng konstruktiv?","options":["Hamma oldida keskin haqorat qilish","Maqsad va aniq xulq qoidalarini eslatib, faol vazifaga jalb qilish","Darsni to‘xtatib qo‘yish","Vazifani bekor qilish"],"answer":1,"explanation":"Samarali sinf boshqaruvi ijobiy qoidalar va ishtirokni kuchaytiradi.","cognitive":"qollash","difficulty":3},{"n":23,"construct":"PM.GEN.05","stem":"Sinf rahbarining ota-onalar bilan ishlashidagi muhim vazifa qaysi?","options":["Faqat rasmiy xat yozish","O‘quvchining rivojlanishini muhokama qilish va hamkorlikni yo‘lga qo‘yish","Boshqa oilalar ma’lumotini oshkor qilish","O‘quvchining fikrini inkor etish"],"answer":1,"explanation":"Sinf rahbari maktab va oilaning hamkorligini muvofiqlashtiradi.","cognitive":"bilish","difficulty":2},{"n":24,"construct":"PM.GEN.05","stem":"Sinf rahbari o‘quvchi haqidagi nozik ma’lumot bilan ishlayapti. Eng to‘g‘ri yo‘l qaysi?","options":["Ommaviy kanalga yuborish","Ruxsatsiz do‘stlarga aytish","Vakolatli shaxslar bilan zarur doirada maxfiy muhokama qilish","Faylni nazoratsiz ochiq qoldirish"],"answer":2,"explanation":"Sinf hujjatlarida shaxsiy ma’lumotlarning maxfiyligi muhim.","cognitive":"qollash","difficulty":3},{"n":25,"construct":"PM.GEN.06","stem":"Pedagogik taktning mohiyati nima?","options":["Barchani bir xil jazolash","Vaziyatga mos, hurmatli va me’yorli pedagogik muomala","Har doim ovozni ko‘tarish","O‘quvchi fikrini inkor qilish"],"answer":1,"explanation":"Pedagogik takt hurmatni saqlagan holda vaziyatga mos munosabatdir.","cognitive":"bilish","difficulty":2},{"n":26,"construct":"PM.GEN.06","stem":"O‘quvchi noto‘g‘ri javob berdi. Qaysi munosabat pedagogik etikaga mos?","options":["Sinf oldida masxara qilish","Shaxsiyatiga tegish","Xatoni muloyim tahlil qilib, fikrlashga yo‘naltirish","Boshqa darslarga kiritmaslik"],"answer":2,"explanation":"Xatoni shaxsga emas, yechimga qaratilgan qayta aloqa bilan tahlil qilish kerak.","cognitive":"qollash","difficulty":3},{"n":27,"construct":"PM.GEN.07","stem":"O‘quvchining kayfiyati va holatini noverbal belgilar orqali sezishga doir qobiliyat qaysi?","options":["Perseptiv qobiliyat","Arifmetik qobiliyat","Texnik qurilma malakasi","Jismoniy chidamlilik"],"answer":0,"explanation":"Perseptiv qobiliyat o‘quvchini idrok qilish va holatini anglashga taalluqli.","cognitive":"bilish","difficulty":2},{"n":28,"construct":"PM.GEN.07","stem":"Murakkab qoidani sodda, tushunarli misolga aylantira olish ko‘proq qaysi pedagogik qobiliyat?","options":["Faqat tashkilotchilik","Didaktik qobiliyat","Faqat sport qobiliyati","Faqat artistlik"],"answer":1,"explanation":"Didaktik qobiliyat bilimni o‘quvchiga tushunarli shaklda yetkazishga yordam beradi.","cognitive":"qollash","difficulty":3},{"n":29,"construct":"PM.GEN.08","stem":"Muammoli ta’lim usulining markazida nima turadi?","options":["Tayyor javobni yodlash","O‘quvchi izlanib yechadigan muammoli vaziyat","Faqat videoni tomosha qilish","Hammaning bir xil nusxa ko‘chirishi"],"answer":1,"explanation":"Muammoli ta’lim fikrlash va izlanish orqali yechim topishga yo‘naltiradi.","cognitive":"bilish","difficulty":2},{"n":30,"construct":"PM.GEN.08","stem":"O‘quvchilardan birining ko‘rishi zaif. Raqamli topshiriqda qanday moslashtirish to‘g‘ri?","options":["Topshiriqdan chetlatish","Faqat mayda shrift ishlatish","Matnni kattalashtirish va mos yordamchi vositalarni berish","Faqat og‘zaki tanbeh berish"],"answer":2,"explanation":"Inklyuziv yondashuv ta’limga teng kirish imkonini yaratadi.","cognitive":"mulohaza","difficulty":4},{"n":31,"construct":"PM.MET.01","stem":"Informatika o‘qitish metodikasining asosiy vazifasi qaysi?","options":["Faqat qurilma narxlarini solishtirish","Nimani, nima uchun va qanday o‘qitishni ilmiy asoslash","Faqat baholar ro‘yxatini saqlash","Faqat sinfning yoritilishini hisoblash"],"answer":1,"explanation":"Metodika mazmun, maqsad va o‘qitish yo‘lini uyg‘unlashtiradi.","cognitive":"bilish","difficulty":2},{"n":32,"construct":"PM.MET.01","stem":"Algoritm mavzusida nazariya bilan amaliyotni bog‘lashga mos mashg‘ulot qaysi?","options":["Faqat ta’rifni ko‘chirtirish","Tayyor dastur natijasini ko‘rsatib yakunlash","Avval algoritmni modellashtirib, keyin kod yozish va testlash","Barcha xatolarni yashirish"],"answer":2,"explanation":"Model → dastur → test zanjiri algoritmik tafakkurni qo‘llashga xizmat qiladi.","cognitive":"qollash","difficulty":3},{"n":33,"construct":"PM.MET.02","stem":"O‘qitish metodi va usulining farqi qaysi javobda to‘g‘ri ifodalangan?","options":["Usul butun pedagogik maqsad, metod esa kichik bir amal","Metod o‘qitishni tashkil etish yo‘li, usul uning tarkibiy amali","Ikkalasi ham faqat texnik qurilma","Metod faqat darsdan tashqarida ishlaydi"],"answer":1,"explanation":"Metod umumiy tashkil etish yo‘li, usul esa uning tarkibiy qismidir.","cognitive":"bilish","difficulty":2},{"n":34,"construct":"PM.MET.02","stem":"O‘qituvchi ma’lumotlar bazasi mavzusida loyiha metodini tanladi. Eng mos faoliyat qaysi?","options":["Faqat atamalarni yodlash","Faqat slayd sanash","Vazifani tahlil qilib, kichik baza loyihalash va taqdim etish","Faqat tayyor javobni yozish"],"answer":2,"explanation":"Loyiha metodi real mahsulot yaratish va qarorni asoslashni talab qiladi.","cognitive":"qollash","difficulty":3},{"n":35,"construct":"PM.MET.03","stem":"O‘quvchilar `for` sikli bir marta kam takrorlanadi deb o‘ylamoqda. Eng foydali metodik harakat qaysi?","options":["Faqat ta’rifni qayta o‘qish","Indekslar izini jadvalda ko‘rsatib, chegaraviy qiymatlarni sinash","Savolni umuman bermaslik","Barcha kodni yashirish"],"answer":1,"explanation":"Trace table va kichik testlar sikl chegaralarini konkret ko‘rsatadi.","cognitive":"mulohaza","difficulty":4},{"n":36,"construct":"PM.MET.03","stem":"Python kodida xatoga duch kelgan o‘quvchiga o‘qituvchi birinchi bo‘lib nima taklif qilishi kerak?","options":["Butun kodni o‘qituvchi qayta yozib berishi","Xatoni ko‘rmasdan javobni berish","Xabarni o‘qish, taxmin tuzish va minimal kirishda xatoni qayta tekshirish","Dasturlashni to‘xtatish"],"answer":2,"explanation":"Xatoni o‘qish, gipoteza va minimal test debugging ko‘nikmasini oshiradi.","cognitive":"mulohaza","difficulty":4}]$data$::jsonb)
    as t(n int, construct text, stem text, options jsonb, answer int, explanation text, cognitive text, difficulty int)
  loop
    select c.id, l.id into v_construct, v_lesson
      from public.constructs c
      join public.lesson_constructs lc on lc.construct_id=c.id
      join public.lessons l on l.id=lc.lesson_id
     where c.code=r.construct and c.is_active
       and l.status='published'::public.content_status
     order by l.id limit 1;
    if v_construct is null or v_lesson is null then
      raise exception 'professional_source_lesson_missing: %', r.construct;
    end if;
    v_qid := ('75000000-0000-4000-8000-'||lpad(r.n::text,12,'0'))::uuid;
    insert into public.questions(
      id, subject_id, construct_id, group_code, format, cognitive, difficulty,
      stem_md, status, source_reference, source_lesson_id
    )
    values (
      v_qid, v_subject, v_construct,
      case when r.construct like 'KS.%' then 'KS'
           when r.construct like 'PM.GEN.%' then 'PM.GEN'
           else 'PM.MET' end,
      'Y1'::public.question_format, r.cognitive::public.cognitive_level,
      r.difficulty, r.stem, 'published'::public.content_status,
      'authored:professional-15:v1:'||r.construct||':'||r.n, v_lesson
    )
    on conflict (id) do nothing;
    for i in 0..3 loop
      v_oid := ('76000000-0000-4000-8000-'||lpad((r.n*10+i)::text,12,'0'))::uuid;
      insert into public.question_options(id, question_id, side, order_idx, content_md)
      values (v_oid, v_qid, 'a', i+1, r.options->>i)
      on conflict (id) do nothing;
    end loop;
    v_oid := ('76000000-0000-4000-8000-'||lpad((r.n*10+r.answer)::text,12,'0'))::uuid;
    insert into public.question_keys(question_id, payload, explanation_md)
    values (v_qid, jsonb_build_object('correct_option_id',v_oid), r.explanation)
    on conflict (question_id) do nothing;
  end loop;
end
$seed$;
commit;
